using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;
namespace Iris {
    public sealed class AddonCoreTestHost : IAddonPlatformHost,IDisposable {
        public readonly List<string> Calls=new List<string>();public readonly ManualResetEventSlim Entered=new ManualResetEventSlim(false),Release=new ManualResetEventSlim(true);public int Inspections;public bool MissingProtocol;
        public bool BlockFiles;public bool FileExists(string p){if(BlockFiles){Entered.Set();Release.Wait();}return true;}public bool DirectoryExists(string p){return true;}
        public void Launch(string t,string a,string d){lock(Calls)Calls.Add("launch:"+t+"|"+a);}public void Folder(string p){lock(Calls)Calls.Add("folder:"+p);}public void Shortcut(string p,ushort[] k){lock(Calls)Calls.Add("keys:"+p+":"+string.Join(",",k));}public void DiscordShare(){lock(Calls)Calls.Add("share");}
        public AddonEnvironmentSnapshot Inspect(CancellationToken token){Interlocked.Increment(ref Inspections);Entered.Set();Release.Wait(token);var e=new AddonEnvironmentSnapshot{SpotifyConnected=true,DiscordTarget=@"C:\Discord\Update.exe",ChatGptTarget="OpenAI.Codex_test!App"};if(!MissingProtocol)foreach(var p in new[]{"steam","codex","ms-settings"})e.Protocols.Add(p);e.Processes.UnionWith(new[]{"Discord","Codex","notepad"});return e;}
        public AddonResult ExecutePlatform(AddonDefinition d,AddonAction a,AddonExecutionContext c,CancellationToken t){t.ThrowIfCancellationRequested();lock(Calls)Calls.Add("platform:"+d.Operation+":"+c.Confirmed);return AddonResult.State("Aufzeichnungshost; nicht nativ ausgeführt","fixture");}
        public void Dispose(){Entered.Dispose();Release.Dispose();}
    }
    public static class AddonCoreQa {
        public static void InspectNative(string directory){Directory.CreateDirectory(directory);var log=new List<string>();using(var timeout=new CancellationTokenSource(5000))try{var task=Task.Factory.StartNew(()=>new NativeAddonHost().Inspect(timeout.Token,true));if(!task.Wait(6000))throw new TimeoutException("Appkatalog reagiert nicht rechtzeitig.");var env=task.Result;log.Add("Read-only native dependency probe (no action dispatch):");log.Add("Protocols: "+string.Join(", ",env.Protocols.OrderBy(p=>p)));log.Add("Discord installation found: "+!string.IsNullOrEmpty(env.DiscordTarget));log.Add("Registered ChatGPT/Codex app: "+(string.IsNullOrEmpty(env.ChatGptTarget)?"not detected":env.ChatGptTarget));log.Add("Note: "+env.Note);log.Add("Only installed-app, protocol and process metadata read. No programs started, clipboard/microphone/audio/UAC untouched.");}catch(Exception ex){log.Add("Native dependency probe incomplete: "+ex.GetBaseException().Message);}File.WriteAllLines(Path.Combine(directory,"addon-native-dependencies.txt"),log);}
        static void Need(bool condition,string message){if(!condition)throw new Exception(message);}
        static AddonPackage Package(string kind){return AddonCatalog.Builtins().First(p=>p.Actions.Any(a=>a.Kind==kind));}
        static AddonExecutionContext Context(AddonPackage p,string id){return new AddonExecutionContext{BindingId=id,PackageId=p.Id};}
        static AddonResult Finish(Task<AddonResult> task){Need(task.Wait(4000),"Engine test exceeded timeout");return task.Result;}
        public static void Run(string directory){var log=new List<string>();try{
            Directory.CreateDirectory(directory);var modules=AddonCatalog.Builtins().ToArray();Need(modules.Length==12&&modules.Select(p=>p.Id).Distinct().Count()==12,"Module identity");Need(modules.All(p=>AddonCatalog.CheckPackage(p)==null)&&AddonRegistry.Definitions.Select(d=>d.Kind).Distinct().Count()==AddonRegistry.Definitions.Count(),"Registry validation");log.Add("PASS: Twelve modules; unique registered action kinds, categories, icons and validated declarative manifests.");
            ushort[] chord;Need(AddonRunner.TryChord("F8",out chord)&&chord.Single()==0x77&&AddonRunner.TryChord("F24",out chord)&&!AddonRunner.TryChord("F25",out chord)&&!AddonRunner.TryChord("A",out chord),"Single function-key configuration");
            var legacy=Path.Combine(directory,"legacy-addons.json");File.WriteAllText(legacy,"{\"Format\":1,\"Packages\":[{\"Id\":\"iris.windows\",\"Name\":\"Windows\",\"Enabled\":false,\"Actions\":[{\"Id\":\"screenshot\",\"Title\":\"Screenshot\",\"Kind\":\"screenshot\"}]}],\"Slots\":[{\"Position\":3,\"PackageId\":\"iris.windows\",\"Action\":{\"Id\":\"screenshot\",\"Title\":\"Meine Aufnahme\",\"Kind\":\"screenshot\"}}]}");
            var original=File.ReadAllText(legacy);var deck=AddonCatalog.Load(legacy);Need(deck.At(3).Action.Title=="Meine Aufnahme"&&deck.At(3).ProfileId=="default"&&!deck.Packages[0].Enabled&&deck.Packages[0].Actions.Count>10&&File.ReadAllText(legacy)==original,"Migration changed bindings, state or source file");string identity=deck.At(3).BindingId;deck.At(3).Action.Icon="\uE8F2";AddonCatalog.Save(Path.Combine(directory,"roundtrip.json"),deck);var again=AddonCatalog.Load(Path.Combine(directory,"roundtrip.json"));Need(again.At(3).BindingId==identity&&again.At(3).Action.Icon=="\uE8F2","Binding/icon persistence");log.Add("PASS: Format-1 migration preserves custom labels, positions, disabled state and original file; stable binding/profile context and icon survive atomic roundtrip.");
            Need(AddonCatalog.Check(new AddonAction{Id="bad",Title="bad",Kind="program",Target=@"C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe"},true)!=null,"Interpreter launch allowed");Need(AddonCatalog.Check(new AddonAction{Id="bad",Title="bad",Kind="discord-channel",Target="https://evil.example/channels/1/2"},true)!=null,"Discord channel escape");
            deck.At(3).Action.Kind="program";deck.At(3).Action.Target=@"C:\Windows\System32\shutdown.exe";AddonCatalog.Save(Path.Combine(directory,"legacy-command-host.json"),deck);var preserved=AddonCatalog.Load(Path.Combine(directory,"legacy-command-host.json"));Need(preserved.At(3).Action.Target.EndsWith("shutdown.exe")&&AddonCatalog.Check(preserved.At(3).Action,true)!=null,"Legacy command binding is discarded or allowed to execute");
            using(var host=new AddonCoreTestHost())using(var engine=new AddonActionEngine(host)){
                var pkg=Package("steam");var action=pkg.Actions.First(a=>a.Kind=="steam").Copy();action.Target="570";var ctx=Context(pkg,"duplicate");host.Release.Reset();var first=engine.ExecuteAsync(pkg,action,ctx,CancellationToken.None);Need(host.Entered.Wait(2000),"Worker not entered");var second=Finish(engine.ExecuteAsync(pkg,action,ctx,CancellationToken.None));Need(second.Code==AddonResultCode.Busy&&host.Calls.Count==0,"Duplicate was dispatched");action.Target="730";host.Release.Set();Need(Finish(first).Success&&host.Calls.Single()=="launch:steam://rungameid/570|"&&engine.ActiveCount==0,"Snapshot/result/idle lost");
                pkg.Enabled=false;int count=host.Calls.Count;Need(Finish(engine.ExecuteAsync(pkg,action,Context(pkg,"off"),CancellationToken.None)).Code==AddonResultCode.Disabled&&host.Calls.Count==count,"Disabled package ran");pkg.Enabled=true;
                host.Release.Reset();host.Entered.Reset();var cancellation=engine.ExecuteAsync(pkg,action,Context(pkg,"cancel"),CancellationToken.None);Need(host.Entered.Wait(2000),"Cancellation worker not entered");engine.Cancel("cancel");Need(Finish(cancellation).Code==AddonResultCode.Cancelled&&host.Calls.Count==count,"Cancelled action dispatched");host.Release.Set();
                host.MissingProtocol=true;Need(Finish(engine.ExecuteAsync(pkg,action,Context(pkg,"missing"),CancellationToken.None)).Code==AddonResultCode.Unavailable&&host.Calls.Count==count,"Missing dependency dispatched");host.MissingProtocol=false;
                var danger=Package("windows-shutdown");var shutdown=danger.Actions.First(a=>a.Kind=="windows-shutdown");var confirmation=Context(danger,"risk");Need(Finish(engine.ExecuteAsync(danger,shutdown,confirmation,CancellationToken.None)).Code==AddonResultCode.ConfirmationRequired&&host.Calls.Count==count,"Risk ran without confirmation");confirmation.Confirmed=true;Need(Finish(engine.ExecuteAsync(danger,shutdown,confirmation,CancellationToken.None)).Success&&host.Calls.Last()=="platform:Shutdown:True","Confirmed risk not routed to recording host");
                var ai=Package("chatgpt-new");Need(Finish(engine.ExecuteAsync(ai,ai.Actions.First(a=>a.Kind=="chatgpt-new"),Context(ai,"newchat"),CancellationToken.None)).Success&&host.Calls.Last()=="launch:codex://threads/new|","Chat route changed");var draft=ai.Actions.First(a=>a.Kind=="chatgpt-summary");Need(Finish(engine.ExecuteAsync(ai,draft,Context(ai,"draft"),CancellationToken.None)).Success&&host.Calls.Last().StartsWith("platform:PrepareChatDraft:"),"Draft route changed");
                var unavailable=ai.Actions.First(a=>a.Kind=="chatgpt-selection");count=host.Calls.Count;Need(Finish(engine.ExecuteAsync(ai,unavailable,Context(ai,"unsupported"),CancellationToken.None)).Code==AddonResultCode.Unavailable&&host.Calls.Count==count,"Unsupported placeholder executed");
                var bad=new AddonAction{Id="a",Title="a",Kind="program",Target=@"C:\Windows\powershell.exe"};Need(Finish(engine.ExecuteAsync(ai,bad,Context(ai,"unsafe"),CancellationToken.None)).Code==AddonResultCode.Failed&&host.Calls.Count==count,"Interpreter escaped runtime validation");
                host.Release.Reset();host.Entered.Reset();var ending=engine.ExecuteAsync(ai,ai.Actions.First(a=>a.Kind=="chatgpt-new"),Context(ai,"exit"),CancellationToken.None);Need(host.Entered.Wait(2000),"Shutdown worker not entered");engine.Dispose();Need(Finish(ending).Code==AddonResultCode.Cancelled&&engine.ActiveCount==0,"Engine does not stop");
            }
            using(var fileHost=new AddonCoreTestHost{BlockFiles=true})using(var fileEngine=new AddonActionEngine(fileHost)){fileHost.Release.Reset();var p=Package("program");var action=new AddonAction{Id="file",Title="Dateiprüfung",Kind="program",Target=@"C:\QA\example.exe"};var job=fileEngine.ExecuteAsync(p,action,Context(p,"file-cancel"),CancellationToken.None);Need(fileHost.Entered.Wait(2000),"File check not entered");fileEngine.Cancel("file-cancel");fileHost.Release.Set();Need(Finish(job).Code==AddonResultCode.Cancelled&&fileHost.Calls.Count==0,"Cancelled file check launched a program");}
            log.Add("PASS: Async action snapshots, in-flight duplicate rejection, disabled modules, cancellation including slow legacy file checks, dependency failure, structured results and shutdown without native commands.");
            log.Add("PASS: Explicit runtime confirmation, interpreter rejection, Discord-link restrictions, unsupported actions and ChatGPT local-chat/draft routes. System actions executed only by recording host; no programs, microphone, clipboard, audio writes or UAC touched.");log.Add("ALL ADDON CORE CHECKS PASSED");
        }catch(Exception ex){Environment.ExitCode=1;log.Add("FAILED: "+ex);}File.WriteAllLines(Path.Combine(directory,"addon-core-test.txt"),log);}
    }
}
